const un=s=>(s||'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"');
const T=n=>{try{const j=$(n).first().json;return typeof j==='string'?j:(j.data||j.body||'');}catch(e){return '';}};
