function rss(n,src){const x=un(T(n));const items=[...x.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m=>m[1]);return items.map(it=>{const g=t=>un(((it.match(new RegExp('<'+t+'>([\\s\\S]*?)<\\/'+t+'>'))||[])[1]||'').replace(/<!\[CDATA\[|\]\]>/g,'')).trim();return {title:g('title'),company:g('dc:creator')||src,link:g('link'),date:g('pubDate'),src};});}
